 const errors=result.diagnostics.filter(d=>d.severity==='error').length;$('#error-count').textContent=errors;$('#error-count').classList.toggle('has-errors',errors>0);$('#inline-diagnostics').innerHTML=`<span class="dot ${errors?'red':'green'}"></span> ${errors?errors+' '+(errors===1?'error':'errors'):'No issues'}`;
