   const toolbar=`<div class="panel-tools"><select id="bytecode-format" aria-label="Disassembly format"><option value="cil" ${cil?'selected':''}>ECMA-335 CIL</option><option value="ir" ${!cil?'selected':''}>Decoded VM IR</option></select><span>Method:</span><select id="bytecode-method">${methods.map(m=>`<option value="${m.id}" ${m.id===selected.id?'selected':''}>${E(m.qualifiedName)}</option>`).join('')}</select><span class="panel-spacer"></span><span>${state.buildDirty?'Last successful build':formatBytes(state.assembly?.length??0)+' PE/CLI'}</span></div>`;
